var options = new SettingOptions { AppCode = "shop" };
var catalog = new SettingCatalog([new LinksSettings()], kinds, options, new ScopeRegistry(null), new AppKeyRing());

var key = "links.token-length";

// Expected: section "links", kind "integer", default "6", and 5 keys in the catalog.

var kind = new IntegerSettingKind();
var rules = new SettingRules { Min = 4, Max = 64 };

// " 012 " is trimmed and cleaned up: true, value "12".
var fits = kind.TryNormalize(" 012 ", rules, out var value, out _);

// 100 is above Max = 64: false, error "settings.errors.range". Nothing is thrown.
var tooBig = kind.TryNormalize("100", rules, out _, out var error);

var kind = new DurationSettingKind();

// Thirty seconds, written with colons: accepted.
var full = kind.TryNormalize("00:00:30", null, out var value, out _);

// A bare 30 would mean 30 days, so it is refused with "settings.errors.duration".
var bare = kind.TryNormalize("30", null, out _, out var error);

var names = new SettingRules { Options = ["alpha", "beta"] };

// The repeated BETA is dropped and the case follows the rules: "beta,alpha".
new ListSettingKind().TryNormalize("Beta, alpha, BETA", names, out var items, out _);

// A choice must be one of the options; ALPHA becomes "alpha".
new ChoiceSettingKind().TryNormalize("ALPHA", names, out var one, out _);

// gamma is not an option: "settings.errors.choice".
new ChoiceSettingKind().TryNormalize("gamma", names, out _, out var error);

