public sealed class BillingSettings : ISettingProvider
{
    public IEnumerable<SettingSection> GetSections()
    {
        yield return new SettingSection
        {
            Code = "billing",
            TitleKey = "settings.sections.billing.title",
            ViewPerm = "billing.view",
            EditPerm = "billing.edit",
            Items =
            [
                // Each tenant may have its own limit; without one it is 100.
                new() { Key = "billing.limit", Kind = SettingCodes.Kind.Integer, Default = "100", Scopable = true, Rules = new() { Min = 1 } },
                // Only usd or eur are accepted.
                new() { Key = "billing.currency", Kind = SettingCodes.Kind.Choice, Default = "usd", Rules = new() { Options = ["usd", "eur"] } },
                // A comma-separated list, such as "owner, accountant".
                new() { Key = "billing.notify", Kind = SettingCodes.Kind.List, Default = "owner" },
                // A secret has no default in code; an admin sets it and it is stored encrypted.
                new() { Key = "billing.gateway-key", Kind = SettingCodes.Kind.Text, Access = SettingAccess.Secret }
            ]
        };
    }
}

