public sealed class AdminGate : ISettingGate
{
    public ValueTask<bool> CanAsync(string permission, Scope scope, CancellationToken token = default)
    {
        // A real gate checks the current user's roles. This one lets everyone view and edit the links section.
        var allowed = permission is "settings.view" or "settings.edit";
        return ValueTask.FromResult(allowed);
    }
}

public sealed class LinksValidator : ISettingSectionValidator
{
    public string Section => "links";

    public ValueTask<IReadOnlyList<FieldError>> ValidateAsync(SettingDraft draft, CancellationToken token = default)
    {
        List<FieldError> errors = [];

        // The draft holds the new values plus the unchanged ones, so this sees the timeout the section will really have.
        if (draft.Get<TimeSpan>("links.timeout") > TimeSpan.FromMinutes(5))
            errors.Add(new FieldError("links.timeout", "links.errors.timeout", "links.errors.timeout"));

        return ValueTask.FromResult<IReadOnlyList<FieldError>>(errors);
    }
}

public sealed class LinksProbe : ISettingProbe
{
    public string Section => "links";

    public async ValueTask<OSResult> ProbeAsync(SettingDraft draft, CancellationToken token = default)
    {
        // Try the new base URL before saving it; if it does not answer, the save stops with links.errors.unreachable.
        using var client = new HttpClient();
        using var reply = await client.GetAsync(draft.Get<string>("links.base-url"), token);

        return reply.IsSuccessStatusCode ? OSResult.Ok() : OSResult.Unavailable("links.errors.unreachable", "links.errors.unreachable");
    }
}

// Both the validator and the probe say Section => "links", so they run only when links is saved.
services.AddOSSettingGate<AdminGate>();
services.AddOSSettingValidator<LinksValidator>();
services.AddOSSettingProbe<LinksProbe>();

// Read first: each item carries the Version the save must send back.
