var length = section.Data!.Items.Single(item => item.Key == "links.token-length");
var timeout = section.Data.Items.Single(item => item.Key == "links.timeout");

var saved = await store.SaveAsync(new SettingSaveModel
{
    Section = "links",
    Scope = Scope.App,
    Changes =
    [
        // Set token length to 20.
        new() { Key = length.Key, Value = "20", Version = length.Version },

        // Remove the stored timeout so the default 00:00:30 applies again.
        new() { Key = timeout.Key, Reset = true, Version = timeout.Version }
    ]
}, token);

